SELECT COUNT(*) FROM (
    SELECT content_key, 
        jsonb_array_length(jsonb_path_query_array(tiernotices, '$.*.* ? (@ != null && @ != "")')) AS total_promo_notes
    FROM promo_info
) sub WHERE total_promo_notes > 0;

SELECT COUNT(DISTINCT srkeys) FROM show_rollups sr
JOIN promo_info pi ON sr.srkeys = pi.content_key
WHERE jsonb_array_length(jsonb_path_query_array(pi.tiernotices, '$.*.* ? (@ != null && @ != "")')) > 0;

WITH promo_counts AS (
    SELECT content_key, 
        jsonb_array_length(jsonb_path_query_array(tiernotices, '$.*.* ? (@ != null && @ != "")')) AS total_promo_notes
    FROM promo_info
)
SELECT * FROM promo_counts WHERE total_promo_notes > 0 ORDER BY content_key;

