SELECT COUNT(*) FROM (
    SELECT c.content_key, 
        jsonb_array_length(jsonb_path_query_array(pi.tiernotices, '$.*.* ? (@ != null && @ != "")')) AS total_promo_notes
    FROM core c LEFT JOIN promo_info pi ON c.content_key = pi.content_key
) sub WHERE total_promo_notes > 0;

SELECT COUNT(*) FROM (
    SELECT c.content_key, 
        COALESCE(jsonb_array_length(jsonb_path_query_array(pi.tiernotices, '$.*.* ? (@ != null && @ != "")')), 0) AS total_promo_notes
    FROM core c LEFT JOIN promo_info pi ON c.content_key = pi.content_key
) sub;

SELECT content_key, 
    (SELECT COUNT(*) FROM jsonb_each(tiernotices::text) AS t(val) WHERE val IS NOT NULL AND val != 'null' AND val != '')
FROM promo_info LIMIT 5;

SELECT content_key, COUNT(*) AS total_promo_notes FROM (
    SELECT content_key, kv.value
    FROM promo_info, jsonb_each_text(tiernotices) AS ft(ft_key, ft_val), jsonb_each_text(ft.ft_val::jsonb) AS kv(kv_key, kv_value)
    WHERE kv.value IS NOT NULL AND kv.value != ''
) sub GROUP BY content_key ORDER BY content_key;

